/* Community prototype: local demo identity, never an authentication boundary. */
(() => {
'use strict';
const admin=!!document.querySelector('[data-community-admin]');
const KEY='noodo-community-v2', SESSION='noodo-community-demo';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const drafts={}, PRESENCE='noodo-presence-v1-', presenceId=crypto.randomUUID();
const emojiGroups={Caras:[['😀','Sonrisa'],['😄','Alegría'],['😂','Risa'],['😍','Me encanta'],['😎','Genial'],['🥹','Emoción'],['🤔','Pensando'],['😴','Sueño'],['🥳','Celebración'],['😭','Llanto'],['🤩','Asombro'],['😊','Feliz']],Gestos:[['👋','Hola'],['👏','Aplausos'],['🙌','Celebrar'],['🤘','Rock'],['👍','Me gusta'],['✌️','Paz'],['💪','Fuerza'],['🙏','Gracias']],Música:[['🎵','Nota musical'],['🎶','Notas musicales'],['🎤','Micrófono'],['🎸','Guitarra'],['🥁','Batería'],['🎹','Piano'],['🎧','Audífonos'],['🎷','Saxofón'],['🎺','Trompeta'],['🎻','Violín']],Símbolos:[['💜','Corazón violeta'],['🔥','Fuego'],['✨','Brillos'],['⭐','Estrella'],['💯','Cien'],['🚀','Cohete'],['✅','Listo'],['⚡','Energía']]};
function avatarKey(){return 'noodo-avatar-v1-'+encodeURIComponent(identity()?.name?.trim().toLowerCase()||'demo');}
function myAvatar(){try{return window.noodoAvatar.normalize(JSON.parse(localStorage.getItem(avatarKey()))||{});}catch{return window.noodoAvatar.normalize();}}
function leavePresence(){try{localStorage.removeItem(PRESENCE+presenceId);}catch{} }
function activeRoom(){return !admin&&identity()&&host&&!host.hidden&&!host.closest('[hidden]')&&tab==='rooms'&&room;}
function pulse(){if(!activeRoom()){leavePresence();return;}try{localStorage.setItem(PRESENCE+presenceId,JSON.stringify({id:presenceId,profile:avatarKey(),room,name:identity().name,avatar:myAvatar(),seen:Date.now()}));}catch{}paintParticipants();}
function paintParticipants(){const el=host?.querySelector('#co-members');if(!el)return;const all=new Map();try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key?.startsWith(PRESENCE))continue;let p;try{p=JSON.parse(localStorage.getItem(key));}catch{continue;}if(p&&p.room===room&&Date.now()-p.seen<30000){const old=all.get(p.profile);if(!old||p.seen>old.seen)all.set(p.profile,p);}}}catch{}
if(activeRoom())all.set(avatarKey(),{profile:avatarKey(),name:identity().name,avatar:myAvatar()});
el.innerHTML=[...all.values()].sort((a,b)=>Number(b.profile===avatarKey())-Number(a.profile===avatarKey())).map(p=>`<div class="co-participant">${window.noodoAvatar.render(p.avatar,'Personaje de '+p.name)}<div><strong>${esc(p.name)}${p.profile===avatarKey()?' <small>(tú)</small>':''}</strong><span><i></i>En la sala</span></div></div>`).join('')||'<p class="co-muted">No hay participantes conectados.</p>';host.querySelector('#co-member-count').textContent=String(all.size);}
function editAvatar(){let value=myAvatar();const dialog=document.createElement('dialog');dialog.className='co-avatar-dialog co-root';dialog.setAttribute('aria-labelledby','co-avatar-title');dialog.innerHTML=`<form method="dialog"><div class="co-emoji-heading"><h2 id="co-avatar-title">Tu personaje NOODO</h2><button type="button" data-avatar-cancel aria-label="Cerrar personalización">×</button></div><div class="co-avatar-preview"></div><fieldset><legend>Color de los audífonos</legend><div class="co-avatar-options">${[['lavender','Lavanda'],['violet','Violeta'],['cream','Crema'],['mint','Menta'],['sky','Cielo']].map(([v,n])=>`<button type="button" data-avatar-color="${v}" aria-pressed="${value.color===v}">${n}</button>`).join('')}</div></fieldset><label>Expresión<select name="expression">${[['classic','Clásico'],['happy','Feliz'],['listening','Escuchando música'],['wink','Guiño']].map(([v,n])=>`<option value="${v}" ${value.expression===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Accesorio<select name="accessory">${[['none','Sin accesorio'],['note','Nota musical'],['mic','Micrófono'],['star','Estrella']].map(([v,n])=>`<option value="${v}" ${value.accessory===v?'selected':''}>${n}</option>`).join('')}</select></label><p class="co-muted">Tu personaje te acompaña en las salas y en tus nuevos mensajes.</p><p id="co-avatar-error" role="alert"></p><div class="co-avatar-actions"><button type="button" class="pill outline" data-avatar-cancel>Cancelar</button><button class="pill primary" type="submit">Guardar personaje</button></div></form>`;
document.body.append(dialog);const preview=()=>dialog.querySelector('.co-avatar-preview').innerHTML=window.noodoAvatar.render(value,'Vista previa de tu personaje');preview();dialog.querySelectorAll('[data-avatar-color]').forEach(b=>b.onclick=()=>{value.color=b.dataset.avatarColor;dialog.querySelectorAll('[data-avatar-color]').forEach(c=>c.setAttribute('aria-pressed',String(c===b)));preview();});dialog.querySelectorAll('select').forEach(select=>select.onchange=()=>{value[select.name]=select.value;preview();});dialog.querySelectorAll('[data-avatar-cancel]').forEach(b=>b.onclick=()=>dialog.close());dialog.querySelector('form').onsubmit=e=>{e.preventDefault();try{localStorage.setItem(avatarKey(),JSON.stringify(value));}catch{dialog.querySelector('#co-avatar-error').textContent='No se pudo guardar el personaje. Inténtalo de nuevo.';return;}dialog.close();pulse();};dialog.onkeydown=e=>{if(e.key==='Escape')e.stopPropagation();};dialog.onclose=()=>{dialog.remove();host?.querySelector('[data-avatar-edit]')?.focus();};dialog.showModal();}
function wireChat(){const select=host.querySelector('#co-room-select');if(select)select.onchange=()=>{room=select.value;render();};host.querySelector('[data-avatar-edit]')?.addEventListener('click',editAvatar);
const form=host.querySelector('#co-message-form');if(!form)return;const input=form.querySelector('input'),toggle=form.querySelector('.co-emoji-toggle'),picker=host.querySelector('#co-emoji-picker');let start=input.value.length,end=start;
const remember=()=>{start=input.selectionStart;end=input.selectionEnd;drafts[room]=input.value;};input.addEventListener('input',remember);input.addEventListener('select',remember);input.addEventListener('keyup',remember);input.addEventListener('click',remember);
const close=()=>{picker.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Abrir emoticones');};
function grid(name){host.querySelector('#co-emoji-grid').innerHTML=emojiGroups[name].map(([emoji,label])=>`<button type="button" data-emoji="${emoji}" aria-label="${label}" title="${label}">${emoji}</button>`).join('');host.querySelectorAll('[data-emoji]').forEach(b=>b.onclick=()=>{const emoji=b.dataset.emoji;if(input.value.length-(end-start)+emoji.length>input.maxLength){notice('El mensaje llegó al límite de caracteres.');return;}input.focus();input.setSelectionRange(start,end);input.setRangeText(emoji,start,end,'end');remember();close();});}
grid('Caras');toggle.onclick=()=>{const isOpen=picker.hidden;picker.hidden=!isOpen;toggle.setAttribute('aria-expanded',String(isOpen));toggle.setAttribute('aria-label',isOpen?'Cerrar emoticones':'Abrir emoticones');if(isOpen)picker.querySelector('[data-emoji]')?.focus();};picker.querySelector('[data-emoji-close]').onclick=()=>{close();toggle.focus();};picker.querySelectorAll('[data-emoji-category]').forEach(b=>b.onclick=()=>{grid(b.dataset.emojiCategory);picker.querySelectorAll('[data-emoji-category]').forEach(c=>c.setAttribute('aria-pressed',String(c===b)));});picker.onkeydown=e=>{if(e.key==='Escape'){e.stopPropagation();close();toggle.focus();}};input.addEventListener('focus',close);
}

const disciplines=['Vocalista','Guitarrista','Bajista','Baterista','Arreglista','Productor musical','Compositor','Ingeniero de sonido','DJ','Percusionista'];
const initial={rooms:[{id:'plaza',name:'La plaza',topic:'El punto de encuentro de la escena. Preséntate y comparte lo que estás creando.',open:true},{id:'produccion',name:'Producción y sonido',topic:'De la primera maqueta a la mezcla final.',open:true},{id:'bandas',name:'Bandas y colaboraciones',topic:'Encuentra a las personas con quienes quieres sonar.',open:true}],messages:{},likes:[],passed:[],posts:[{id:'intro',title:'¿Cómo preparas tu primera sesión en estudio?',body:'Compartamos experiencias, equipo y consejos para llegar con todo listo.',category:'Pregunta',author:'Equipo NOODO',owner:'seed',replies:[]},{id:'busqueda',title:'Buscamos guitarrista para un proyecto indie en Cali',body:'Ensayamos los sábados. Buscamos a alguien con ganas de componer y construir repertorio juntos.',category:'Busco artista',author:'Vértice',owner:'seed',replies:[]} ]};
function read(){try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&Array.isArray(v.rooms)&&Array.isArray(v.posts)&&v.messages&&Array.isArray(v.likes)&&Array.isArray(v.passed))return v;}catch{}return structuredClone(initial);}
function save(s){try{localStorage.setItem(KEY,JSON.stringify(s));return true;}catch{notice('No pudimos guardar los cambios. Revisa el almacenamiento del navegador.');return false;}}
function identity(){try{return JSON.parse(sessionStorage.getItem(SESSION));}catch{return null;}}
let tab='rooms',room='plaza',filter='Todas',category='Todos',query='',postId=null,compose=false,personIndex=0;
let host, pending=null;
function notice(text){const n=document.getElementById('community-status');if(n)n.textContent=text;}
function panel(){if(admin)return document.querySelector('[data-community-admin]');let el=document.getElementById('community-page');if(!el){el=document.createElement('section');el.id='community-page';el.className='central-panel experience-panel';el.hidden=true;el.tabIndex=-1;document.getElementById('center-details').append(el);}return el;}
function gate(next,navigation='community'){if(identity()){next();return;}pending=next;host=panel();host.dataset.navigation=navigation;host.onclick=null;host.classList.add('co-root');host.innerHTML=`<div class="co-gate"><span class="co-kicker">COMUNIDAD NOODO</span><h1>Tu próximo encuentro empieza aquí.</h1><p>Entra para conversar, encontrar colaboradores y compartir lo que sabes.</p><div class="co-entry-grid" aria-label="Explora Comunidad">${[
 ['rooms','01','Salas de chat','Comparte lo que suena.','Conversa con personas que viven la música como tú.','Músicos conversando en un encuentro musical'],
 ['match','02','Nodo Match','Encuentra con quién crear.','Conecta con artistas y colaboradores para tu próxima idea.','Dos artistas creando música juntos'],
 ['forum','03','Foro','Las ideas se comparten.','Pregunta, aprende y haz parte de la conversación.','Comunidad creativa compartiendo ideas']
].map(([id,n,title,headline,description,alt],index)=>`<button type="button" class="co-entry-card" data-community-entry="${id}" aria-pressed="${tab===id}"><span class="co-entry-art" style="--entry-image-offset:${index*-100}%"><img src="assets/community/community-triptych.jpg" alt="${alt}" width="1536" height="1024"></span><span class="co-entry-copy"><span class="co-entry-label">${n} · ${title}</span><strong>${headline}</strong><span>${description}</span><span class="co-entry-link">Explorar ${title} <span aria-hidden="true">↗</span></span></span></button>`).join('')}</div><div class="co-demo"><strong>Vista previa con perfil de demostración</strong><p>El registro de cuentas estará disponible al conectar el servicio de usuarios. Esta demo guarda la actividad solo en este navegador.</p><form id="co-demo-form"><label>Tu nombre en la demo<input name="name" maxlength="50" required autocomplete="off" placeholder="¿Cómo te llamas?"></label><button class="pill primary">Entrar a la demo</button></form></div><button class="text-button" data-co="back">Seguir escuchando sin cuenta →</button></div>`;window.noodoWorkspace.showPanel(host);host.querySelectorAll('[data-community-entry]').forEach(button=>button.onclick=()=>{tab=button.dataset.communityEntry;host.querySelectorAll('[data-community-entry]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));host.querySelector('input[name="name"]').focus({preventScroll:true});});host.querySelector('form').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;try{sessionStorage.setItem(SESSION,JSON.stringify({id:'demo',name}));}catch{return;}const run=pending;pending=null;window.noodoWorkspace.closePanel();run?.();};host.querySelector('[data-co]').onclick=()=>window.noodoWorkspace.closePanel();}
function open(){gate(()=>{host=panel();render();window.noodoWorkspace.showPanel(host);window.noodoNavigation?.sync();});}
function people(){const ids=[0,2,3,4,1];return ids.filter(i=>tracks[i]).map((i,n)=>({id:String(i),artist:i,name:tracks[i].artist,image:tracks[i].image,role:[['Vocalista','Compositor'],['Productor musical','Arreglista'],['Guitarrista','Bajista'],['Vocalista','Productor musical'],['Percusionista','Arreglista']][n],genre:genreNames[tracks[i].genre],incoming:n===1,about:tracks[i].description}));}
const btn=(action,text,cls='outline',extra='')=>`<button type="button" class="pill ${cls}" data-co="${action}" ${extra}>${text}</button>`;
function render(){if(!identity()){gate(open);return;}const s=read();host=panel();host.dataset.navigation='community';host.classList.add('co-root');host.innerHTML=`<div class="co-top">${window.noodoPageTitle.render("Comunidad")}<div class="co-user"><span>${esc(identity().name)} · Demo local</span>${btn('logout','Salir','outline')}</div></div><nav class="co-tabs" aria-label="Secciones de Comunidad">${[['rooms','Salas de chat','01'],['match','Nodo Match','02'],['forum','Foro','03']].map(([id,label,n])=>`<button data-co="tab" data-tab="${id}" aria-current="${tab===id?'page':'false'}"><small>${n}</small>${label}</button>`).join('')}</nav><div id="community-status" role="status" aria-live="polite"></div><div class="co-content">${tab==='rooms'?rooms(s):tab==='match'?match(s):forum(s)}</div>`;wire(s);wireChat();pulse();}
function rooms(s){const list=s.rooms.filter(r=>r.open);let selected=list.find(r=>r.id===room);const matches=people().filter(p=>s.likes.includes(p.id)&&p.incoming);const privatePerson=matches.find(p=>'dm-'+p.id===room);if(privatePerson)selected={id:room,name:privatePerson.name,topic:'Conversación de ejemplo después de un match mutuo.'};if(!selected){selected=list[0];room=selected?.id||'';}const messages=s.messages[room]||[];
return `<div class="co-chat"><aside class="co-room-list"><label for="co-room-select">Sala de chat</label><select id="co-room-select">${list.length?`<optgroup label="Salas de NOODO">${list.map(r=>`<option value="${esc(r.id)}" ${r.id===room?'selected':''}># ${esc(r.name)}</option>`).join('')}</optgroup>`:'<option value="">Sin salas abiertas</option>'}${matches.length?`<optgroup label="Mis matches">${matches.map(p=>`<option value="dm-${p.id}" ${room==='dm-'+p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</optgroup>`:''}</select><div class="co-members-heading"><h3>En esta sala</h3><span id="co-member-count">0</span></div><div id="co-members" aria-label="Participantes de la sala"></div><button type="button" class="pill outline co-customize" data-avatar-edit>Personalizar mi personaje</button><p class="co-muted">Presencia local de esta demo.</p></aside><section class="co-conversation">${selected?`<header><h2>${privatePerson?'':'# '}${esc(selected.name)}</h2><p>${esc(selected.topic)}</p></header><div class="co-messages" role="log" aria-label="Mensajes de la sala">${messages.length?messages.map(m=>`<article class="co-message co-avatar-message">${window.noodoAvatar.render(m.avatar||{},'Personaje de '+m.author)}<div><strong>${esc(m.author)}</strong><time>${esc(m.time)}</time><p>${esc(m.text)}</p></div></article>`).join(''):`<div class="co-empty"><span>↗</span><h3>La conversación empieza contigo</h3><p>Preséntate, comparte una idea o haz una pregunta.</p><small>Demo local: los mensajes no se envían a otras personas.</small></div>`}</div><div class="co-compose-wrap"><div id="co-emoji-picker" class="co-emoji-picker" hidden><div class="co-emoji-heading"><strong>Emoticones</strong><button type="button" data-emoji-close aria-label="Cerrar emoticones">×</button></div><div class="co-emoji-categories" aria-label="Categorías de emoticones">${Object.keys(emojiGroups).map((c,i)=>`<button type="button" data-emoji-category="${c}" aria-pressed="${i===0}">${c}</button>`).join('')}</div><div id="co-emoji-grid" class="co-emoji-grid"></div></div><form id="co-message-form" class="co-composer"><button type="button" class="co-emoji-toggle" aria-label="Abrir emoticones" aria-expanded="false" aria-controls="co-emoji-picker">☺</button><input name="message" aria-label="Escribe un mensaje" maxlength="1500" required value="${esc(drafts[room]||'')}" placeholder="Escribe en ${esc(selected.name)}…"><button class="pill primary co-send">Enviar <span aria-hidden="true">→</span></button></form></div>`:'<div class="co-empty"><h2>Aún no hay salas abiertas</h2></div>'}</section></div><section class="co-all-rooms" aria-labelledby="co-all-rooms-title"><h2 id="co-all-rooms-title">Todas las salas</h2><div class="co-room-directory">${list.map(r=>`<button type="button" class="co-room-card" data-co="room" data-room="${esc(r.id)}" aria-current="${r.id===room}"><strong># ${esc(r.name)}</strong><span>${esc(r.topic)}</span><small>${r.id===room?'Estás en esta sala':'Entrar a la sala →'}</small></button>`).join('')||'<p>El equipo NOODO todavía no ha abierto salas.</p>'}</div></section>`;}
function match(s){const options=people().filter(p=>(filter==='Todas'||p.role.includes(filter))&&!s.likes.includes(p.id)&&!s.passed.includes(p.id));const p=options[personIndex%Math.max(options.length,1)];return `<div class="co-match"><aside><span class="co-kicker">ENCUENTRA TU PRÓXIMO NODO</span><h2>Distintas disciplinas.<br>Una misma pasión.</h2><p>Descubre artistas y profesionales con quienes crear.</p><label>Disciplina<select id="co-discipline">${['Todas',...disciplines].map(d=>`<option ${d===filter?'selected':''}>${d}</option>`).join('')}</select></label><p class="co-muted">Me interesa + interés mutuo = un nuevo chat.</p><p class="co-muted">Perfiles y disciplinas de ejemplo. Kora tiene un interés previo simulado para explorar el recorrido del match.</p><p>${s.likes.length} intereses enviados · ${people().filter(p=>p.incoming&&s.likes.includes(p.id)).length} matches</p>${btn('reset','Volver a explorar')}</aside><section>${p?`<article class="co-match-card"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div class="co-match-copy"><span class="co-tag">Cali · ${esc(p.genre)}</span><h2>${esc(p.name)}</h2><div class="co-tags">${p.role.map(r=>`<span>${r}</span>`).join('')}</div><p>${esc(p.about)}</p><a class="text-button" href="artist.html?artist=${p.artist}">Ver perfil de artista ↗</a></div></article><div class="co-match-actions">${btn('pass','× Pasar','outline',`data-person="${p.id}"`)}${btn('like','♡ Me interesa','primary',`data-person="${p.id}"`)}</div>`:`<div class="co-empty"><h2>Ya viste estos perfiles</h2><p>Prueba otra disciplina o vuelve a explorar.</p>${btn('reset','Volver a explorar')}</div>`}</section></div>`;}
function forum(s){const selected=s.posts.find(p=>p.id===postId);if(selected)return `<button class="text-button" data-co="forum-back">← Todas las entradas</button><article class="co-thread"><span class="co-tag">${esc(selected.category)}</span><h2>${esc(selected.title)}</h2><small>Por ${esc(selected.author)}</small><p class="co-body">${esc(selected.body)}</p>${selected.owner==='demo'?btn('delete','Eliminar mi entrada'):''}<h3>${selected.replies.length} respuestas</h3>${selected.replies.map(r=>`<div class="co-reply"><strong>${esc(r.author)}</strong><p>${esc(r.text)}</p></div>`).join('')}<form id="co-reply-form"><label>Tu respuesta<textarea name="reply" required maxlength="3000" rows="4" placeholder="Comparte tu experiencia…"></textarea></label><button class="pill primary">Responder</button></form></article>`;
const categories=['Todos','Pregunta','Busco artista','Pedido','Colaboración'];const list=s.posts.filter(p=>(category==='Todos'||p.category===category)&&window.noodoSearchIndex.normalize(`${p.title} ${p.body} ${p.author}`).includes(window.noodoSearchIndex.normalize(query)));return `<div class="co-forum-header"><div><h2>El conocimiento se comparte.</h2><p>Preguntas, pedidos y búsquedas de la comunidad.</p></div>${btn('compose',compose?'Cancelar':'＋ Nueva entrada','primary')}</div>${compose?`<form id="co-post-form" class="co-post-form"><label>Título<input name="title" required maxlength="140" placeholder="¿Qué quieres compartir o encontrar?"></label><label>Categoría<select name="category">${categories.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></label><label>Contenido<textarea name="body" required rows="5" maxlength="6000"></textarea></label><button class="pill primary">Publicar entrada</button></form>`:''}<div class="co-forum-filters"><label>Categoría<select id="co-category">${categories.map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="co-forum-list">${list.map(p=>`<button class="co-post-row" data-co="post" data-id="${esc(p.id)}"><span class="co-post-icon">${p.category==='Pregunta'?'?':'↗'}</span><span><small>${esc(p.category)}</small><strong>${esc(p.title)}</strong><small>${esc(p.author)}</small></span><span>${p.replies.length}<small>respuestas</small></span></button>`).join('')||'<div class="co-empty">No hay entradas que coincidan con tu búsqueda.</div>'}</div>`;}
function wire(s){host.onclick=e=>{const b=e.target.closest('[data-co]');if(!b)return;const action=b.dataset.co;if(action==='logout'){leavePresence();sessionStorage.removeItem(SESSION);gate(open);return;}if(action==='tab'){tab=b.dataset.tab;postId=null;}if(action==='room'){room=b.dataset.room;tab='rooms';}if(action==='compose')compose=!compose;if(action==='post')postId=b.dataset.id;if(action==='forum-back')postId=null;if(action==='delete'){if(!confirm('¿Eliminar esta entrada y sus respuestas?'))return;s.posts=s.posts.filter(p=>p.id!==postId||p.owner!=='demo');if(!save(s))return;postId=null;}if(action==='pass'||action==='like'){s[action==='like'?'likes':'passed'].push(b.dataset.person);if(!save(s))return;if(action==='like'&&people().find(p=>p.id===b.dataset.person)?.incoming){room='dm-'+b.dataset.person;tab='rooms';}}if(action==='reset'){s.passed=[];if(!save(s))return;}render();if(['tab','post','forum-back'].includes(action))window.noodoNavigation?.enter(host);if(action==='room'){host.querySelector('.co-chat')?.scrollIntoView({block:'start',behavior:'smooth'});host.querySelector('#co-message-form input')?.focus({preventScroll:true});}};
const discipline=host.querySelector('#co-discipline');if(discipline)discipline.onchange=e=>{filter=e.target.value;personIndex=0;render();};const cat=host.querySelector('#co-category');if(cat)cat.onchange=e=>{category=e.target.value;render();};
function form(id,fn){const f=host.querySelector(id);if(f)f.onsubmit=e=>{e.preventDefault();const fresh=read();if(fn(new FormData(f),fresh)===false)return;if(save(fresh)){if(id==='#co-message-form')drafts[room]='';render();}};}
form('#co-message-form',(d,fresh)=>{const text=d.get('message').trim();if(!text)return false;const allowed=fresh.rooms.some(r=>r.id===room&&r.open)||people().some(p=>'dm-'+p.id===room&&p.incoming&&fresh.likes.includes(p.id));if(!allowed){notice('Esta sala ya no está disponible.');return false;}(fresh.messages[room]??=[]).push({author:identity().name,avatar:myAvatar(),text,time:new Date().toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'})});});
form('#co-post-form',(d,fresh)=>{const title=d.get('title').trim(),body=d.get('body').trim();if(!title||!body)return false;fresh.posts.unshift({id:crypto.randomUUID(),title,body,category:d.get('category'),author:identity().name,owner:'demo',replies:[]});compose=false;});
form('#co-reply-form',(d,fresh)=>{const text=d.get('reply').trim(),p=fresh.posts.find(p=>p.id===postId);if(!text||!p)return false;p.replies.push({author:identity().name,text});});const log=host.querySelector('.co-messages');if(log)log.scrollTop=log.scrollHeight;}
function adminRender(){host=panel();const s=read();host.classList.add('co-root');host.innerHTML=`${window.noodoPageTitle.render("Comunidad")}<p class="co-demo">Administración de demostración · cambios locales en este navegador. Esta vista no tiene autenticación administrativa.</p><div id="community-status" role="status"></div><h2>Salas de chat</h2><div class="co-admin-rooms">${s.rooms.map(r=>`<form data-room-edit="${esc(r.id)}"><label>Nombre<input name="name" required maxlength="60" value="${esc(r.name)}"></label><label>Descripción<input name="topic" required maxlength="180" value="${esc(r.topic)}"></label><label>Estado<select name="open"><option value="true" ${r.open?'selected':''}>Abierta</option><option value="false" ${!r.open?'selected':''}>Cerrada</option></select></label><button class="pill outline">Guardar sala</button></form>`).join('')}</div><h2>Crear sala</h2><form id="co-new-room" class="co-admin-new"><label>Nombre<input name="name" required maxlength="60"></label><label>Descripción<input name="topic" required maxlength="180"></label><button class="pill primary">Crear sala</button></form><h2>Entradas del foro</h2>${s.posts.map(p=>`<div class="co-admin-post"><span><strong>${esc(p.title)}</strong><small>${esc(p.author)} · ${esc(p.category)}</small></span><button class="pill outline" data-remove="${esc(p.id)}">Retirar entrada</button></div>`).join('')||'<p>No hay entradas.</p>'}<a class="text-button" href="listen.html?section=community" target="_blank">Abrir Comunidad ↗</a>`;
host.querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const d=new FormData(f),state=read(),name=d.get('name').trim(),topic=d.get('topic').trim();if(!name||!topic)return;const id=f.dataset.roomEdit;if(state.rooms.some(r=>r.id!==id&&r.name.toLowerCase()===name.toLowerCase())){notice('Ya existe una sala con ese nombre.');return;}if(id){const r=state.rooms.find(r=>r.id===id);if(!r)return;Object.assign(r,{name,topic,open:d.get('open')==='true'});}else state.rooms.push({id:crypto.randomUUID(),name,topic,open:true});if(save(state)){adminRender();notice('Sala guardada.');}});host.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(!confirm('¿Retirar esta entrada y sus respuestas?'))return;const state=read();state.posts=state.posts.filter(p=>p.id!==b.dataset.remove);if(save(state))adminRender();});}
if(admin){adminRender();window.addEventListener('storage',e=>{if(e.key===KEY)adminRender();});return;}
setInterval(pulse,10000);window.addEventListener('pagehide',leavePresence);
new MutationObserver(()=>{if(activeRoom())pulse();else leavePresence();}).observe(document.getElementById('center-details'),{attributes:true,attributeFilter:['hidden'],subtree:true});
window.noodoCommunity={open,requireProfile:gate,
 search(value){if(query===value)return;query=value;if(host&&!host.hidden&&identity()&&tab==='forum'&&!postId&&!compose)render();},
 searchEntries(){return [
  ...[['rooms','Salas de chat','Conversa con la comunidad'],['match','Nodo Match','Encuentra artistas y colaboradores'],['forum','Foro','Preguntas, pedidos y colaboraciones']].map(([id,title,subtitle])=>({key:'community:'+id,type:'community',id,title,subtitle})),
  ...(identity()?read().posts.map(p=>({key:'community:post:'+p.id,type:'community',id:p.id,post:true,title:p.title,subtitle:p.category+' · '+p.author,keywords:p.body})):[])
 ];},
 openSearchResult(result){gate(()=>{tab=result.post?'forum':result.id;postId=result.post?result.id:null;query='';host=panel();render();window.noodoWorkspace.showPanel(host);});}
};
document.getElementById('library-community').onclick=()=>window.noodoWorkspace.navigate('listen.html?section=community');
// Capture all existing library/follow actions before their handlers mutate local data.
const protectedSelector='[data-user-playlist-create],#create-library-playlist,[data-save],[data-session-save],[data-artist-save],[data-playlist-add],[data-follow],#save-current,#library-artists,#top-playlists,[data-view="all"],[data-mobile-view="all"],#follow-artist,#follow,#create-playlist,#add-to-playlist';
document.addEventListener('click',e=>{const b=e.target.closest(protectedSelector);if(b&&!identity()){e.preventDefault();e.stopImmediatePropagation();gate(()=>{if(b.isConnected)b.click();else open();},b.dataset.navigation||b.dataset.mobileView||(b.id==='top-playlists'?'playlists':'community'));}},true);
const profile=document.getElementById('profile');profile?.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();if(identity())open();else gate(open);},true);
window.addEventListener('storage',e=>{if(e.key?.startsWith(PRESENCE))paintParticipants();else if(e.key===KEY&&host&&!host.hidden&&identity())render();});
})();
